from langchain.schema import Document
from typing import Optional, Union, Any, List
import ast
import json
from engine import CustomComponent
from config.settings import environment


class JsonParse(CustomComponent):
    display_name: str = "Json 解析器"
    description: str = "根据输入文档和指定的字段路径截取 JSON 中的部分内容"
    beta = False
    documentation = (
        "https://alidocs.dingtalk.com/i/nodes/ydxXB52LJq73bNkAswGGMymQWqjMp697?"
        "cid=438043529:1947991365&corpId=dingc60f3ee02b83212535c2f4657eb6378f&"
        "doc_type=wiki_doc&iframeQuery=utm_medium=im_card&utm_source=im&utm_medium="
        "im_card&utm_scene=team_space&utm_source=im"
    )

    def build_config(self) -> dict:
        # 此处 input 配置为单个输入框，用于填写 JSON 字段的 key 路径，
        # 若需访问嵌套的键请使用英文逗号分隔，例如 "person,name"
        return {
            "document": {"required": True},
            "code": {"show": True if environment != "prod" else False},
            "input": {
                "display_name": "JSON Key Path",
                "info": (
                    "请输入 JSON 中相关的 key 值，若需访问嵌套的键，请使用英文逗号分隔，例如 'person,name'"
                ),
                "is_list": False  # 单个输入框
            }
        }

    def get_value_from_json(self, json_data: Union[dict, list, None], keys: List[str]) -> Any:
        """
        根据给定的嵌套 key 路径获取 JSON 数据中的值

        参数:
            json_data: JSON 数据（通常为字典或列表）
            keys: key 路径列表，例：["person", "name"]

        返回:
            Any: 对应的值；若路径不存在则返回 None
        """
        current_data = json_data
        if current_data is None or not keys:
            return current_data

        for key in keys:
            key = key.strip()
            if not key:
                continue
            try:
                # 如果当前数据为列表，则 key 应是索引
                if isinstance(current_data, list):
                    try:
                        index = int(key)
                    except ValueError:
                        return None
                    if 0 <= index < len(current_data):
                        current_data = current_data[index]
                    else:
                        return None
                # 如果当前数据为字典，则直接通过 key 访问
                elif isinstance(current_data, dict):
                    if key in current_data:
                        current_data = current_data[key]
                    else:
                        return None
                else:
                    return None
            except Exception:
                return None

        return current_data

    def parse_document(self, document: Union[str, dict, Document]) -> dict:
        """
        将输入的文档解析为字典格式

        参数:
            document: 可为 JSON 字符串、字典或 Document 对象

        返回:
            dict: 解析后的 JSON 对象

        异常:
            ValueError: 当文档为空或格式无效时
        """
        if document is None:
            raise ValueError("Document is required but received None.")

        if isinstance(document, dict):
            return document
        elif isinstance(document, str):
            if not document.strip():
                raise ValueError("Empty document string provided.")
            try:
                return json.loads(document)
            except json.JSONDecodeError as exc:
                raise ValueError("Invalid JSON string.") from exc
        elif isinstance(document, Document):
            content = document.page_content
            if not content or not content.strip():
                raise ValueError("Document content is empty.")
            # 先尝试使用 ast.literal_eval 解析（适用于 Python 格式的字典字符串）
            try:
                result = ast.literal_eval(content)
                if isinstance(result, dict):
                    return result
            except Exception:
                pass
            try:
                return json.loads(content)
            except json.JSONDecodeError as exc:
                raise ValueError("Invalid document content format.") from exc
        else:
            raise ValueError("Unsupported document type. Must be str, dict, or Document.")

    def build(self, input: Optional[str] = None, document: Optional[Document] = None) -> Document:
        """
        构建处理结果：
          1. 解析输入的 document，获得 JSON 对象；
          2. 根据 input 中填写的 JSON key path（例如 "person,name"）截取特定数据，
             若 input 为空则返回整个 JSON 对象；
          3. 如果提取结果为字符串，则直接返回其原始值，避免因 json.dumps 导致的额外双引号；
             否则转换成标准 JSON 格式，确保键使用双引号（符合 [stackoverflow.com](https://stackoverflow.com/questions/949449/do-the-json-keys-have-to-be-surrounded-by-quotes) 的规范）。

        参数:
            input: 用于指定 JSON 需要抽取的 key 路径（单个输入框），例如 "person,name"
            document: 包含原始 JSON 数据的 Document 对象

        返回:
            Document: 包含处理后结果的 Document 对象

        异常:
            ValueError: 处理过程中出现错误时
        """
        if document is None:
            raise ValueError("Document is required.")

        try:
            parsed_document = self.parse_document(document)

            if input in (None, "", []):
                # 未指定 key path 时，返回整个 JSON 对象
                result = parsed_document
                result_json = json.dumps(result, ensure_ascii=False)
            else:
                # 拆分输入框内容，按逗号拆分为嵌套的 key 列表
                keys = [k.strip() for k in input.split(",") if k.strip()]
                result = self.get_value_from_json(parsed_document, keys)

                # 如果提取结果为字符串，则直接返回原始值，
                # 避免使用 json.dumps 让字符串产生多余的双引号（参见 [stackoverflow.com](https://stackoverflow.com/questions/21405357/using-double-quotes-inside-json-keys-or-values)）
                if isinstance(result, str):
                    result_json = result
                else:
                    result_json = json.dumps(result, ensure_ascii=False)

            self.repr_value = result_json
            return Document(page_content=result_json)
        except Exception as e:
            raise ValueError(f"Error processing document: {str(e)}") from e

