class AiImageLoader(CustomComponent):
    display_name: str = "AI图片解析"
    description: str = "调用大模型进行图片内容解析"
    beta = False
    documentation = "https://alidocs.dingtalk.com/i/nodes/ydxXB52LJq73bNkAswGGMymQWqjMp697?cid=438043529:1947991365&corpId=dingc60f3ee02b83212535c2f4657eb6378f&doc_type=wiki_doc&iframeQuery=utm_medium=im_card&utm_source=im&utm_medium=im_card&utm_scene=team_space&utm_source=im"

    field_config = {
        "model_name_new": {
            "display_name": "模型选择",
            "type": "select",
            "options": [1]
        },
        "message": {
            "display_name": "输入",
            "info": "传入图像接收用户输入指导模型推理"
        },
        "thinking_budget": {
            "display_name": "思考长度"
        },
        "image": {
            "display_name": "图像",
            "info": "接受一张图像链接作为输入"
        },
        "prompt": {
            "display_name": "系统提示词",
            "info": "需要定义提示模板"
        },
        "code": {"show": True if environment != "prod" else False},
        "isVal": {
            "display_name": "内容安全过滤"
        },
        "maxTokens": {
            "display_name": "最大输出Token"
        }
    }

    def build(
            self,
            model_name_new: str = "",
            prompt: Optional[PromptTemplate] = None,
            message: Optional[PromptTemplate] = None,
            image: Optional[List[Document]] = None,
            thinking_budget: Optional[str] = None,
            isVal: bool = True,
            maxTokens: str = "4000",
            temperature: str = "0.7"
    ) -> Document:
        image_url_list = []

        def is_url(path):
            return path.startswith('http://') or path.startswith('https://')

        def is_file_path(path):
            return os.path.isfile(path)

        def is_base64_image(data: str) -> bool:
            pattern = r'^data:image\/[a-zA-Z]+;base64,'
            return re.match(pattern, data) is not None

        def is_oss_address(path):
            return path.startswith('http://ossaism') or path.startswith('https://ossaism') or path.startswith(
                'https://aism-test')

        def get_mime_type(file_path):
            _, file_ext = os.path.splitext(file_path)
            if file_ext.lower() in ['.jpg', '.jpeg']:
                return 'data:image/jpeg;base64,'
            elif file_ext.lower() == '.png':
                return 'data:image/png;base64,'
            else:
                return 'data:image/jpeg;base64,'

        image_url_list = []

        for img_doc in image or []:
            try:
                contents = img_doc.page_content

                # 处理字符串形式的列表或普通字符串
                if isinstance(contents, str):
                    try:
                        parsed = ast.literal_eval(contents)
                        if isinstance(parsed, list) and all(isinstance(x, str) for x in parsed):
                            contents = parsed
                        else:
                            contents = [contents]
                    except (ValueError, SyntaxError):
                        contents = [contents]
                else:
                    print(f"[跳过] 非法 page_content 类型: {type(contents)}")
                    continue

                # 遍历实际的字符串列表
                for content in contents:
                    try:
                        if is_url(content):
                            image_url_list.append(content)
                        elif is_oss_address(content):
                            oss_tool = OssTool()
                            remote_key = oss_tool.extract_key_from_url(content)
                            unique_id = uuid.uuid4()
                            file_path = f".cache/{unique_id}"
                            oss_tool.download(remote_key, file_path)
                            with open(file_path, 'rb') as file:
                                file_content = file.read()
                                mime_type = get_mime_type(content)
                                encoded_string = mime_type + base64.b64encode(file_content).decode()
                                image_url_list.append(encoded_string)
                        elif is_file_path(content):
                            with open(content, 'rb') as file:
                                file_content = file.read()
                                mime_type = get_mime_type(content)
                                encoded_string = mime_type + base64.b64encode(file_content).decode()
                                image_url_list.append(encoded_string)
                        elif is_base64_image(content):
                            image_url_list.append(content)
                        else:
                            print(f"[跳过] 无效图像格式: {content}")
                    except Exception as e:
                        print(f"[跳过] 图像处理异常: {e}")
            except Exception as e:
                print(f"[跳过] 文档处理异常: {e}")

        if not image_url_list:
            raise ValueError("所有图像均处理失败，未能生成有效的图像输入。")
        callData = {}  # 接口内运行时替换成具体的值
        messages = [
            {"role": "system", "content": ("系统人设" if prompt is None else json_prompt_format(prompt))},
            {"role": "user", "content": [
                                            {"type": "text",
                                             "text": (
                                                 "请使用中文对图像进行描述" if message is None else json_prompt_format(
                                                     message))}
                                        ] + [{"type": "image_url", "image_url": {"url": url}} for url in
                                             image_url_list]}
        ]
        payload = {
            "modelName": model_name_new,
            "messages": messages,
            "max_tokens": str(maxTokens),
            "isVal": isVal,
            "temperature": float(temperature),
        }

        # 增加模型思考字段如果传入，则添加到model_payload中
        if thinking_budget is not None:
            try:
                thinking_budget = int(thinking_budget)
            except Exception:
                pass
            if isinstance(thinking_budget, int):
                if thinking_budget > 0:
                    thinking_type = "enabled"
                else:
                    thinking_type = "disabled"
                payload["thinking"] = {"type": thinking_type}
                payload["thinkingBudget"] = thinking_budget

        payload.update(callData)
        url = settings.MODEL_SERVICE_URL_5
        headers = {'Content-Type': 'application/json'}
        # self.logs(f"请求URL: {url}")
        # self.logs(f"请求头: {headers}")
        # self.logs(f"请求体: {json.dumps(payload, ensure_ascii=False)}")
        documents = self.send_request_with_payload(payload, url, headers)
        response = json.loads(documents.page_content)
        if response.get("code") == 200:
            result = response.get("content")
        else:
            result = response.get("msg")
        self.repr_value = str(result)
        return Document(page_content=str(result))

    def send_request_with_payload(
            self,
            payload: dict,
            url: str,
            headers: dict
    ) -> Document:
        # print(payload)
        document = Document(page_content=str(json.dumps(payload)))
        with requests.Session() as session:
            documents = self.post_document(session, document, url, headers)
        return documents

    def post_document(
            self,
            session: requests.Session,
            document: Document,
            url: str,
            headers: Optional[Document] = None,
    ) -> Document:
        response = session.post(url, headers=headers, data=document.page_content)
        # 检查HTTP请求的状态码是否表示成功
        if response.status_code < 300 or response.status_code > 511:
            try:
                response_json = response.json()
                result = orjson_dumps(response_json, indent_2=False)  # 假设orjson_dumps是已经定义好的函数
            except Exception:
                result = response.text
            return Document(
                page_content=result,
                metadata={
                    "source": url,
                    "headers": headers,
                    "status_code": response.status_code,
                },
            )
        else:
            # 如果状态码不是正常的，抛出异常
            response.raise_for_status()
